def close_order(order_id: str, *, store: OrderStore) -> Receipt:
    order = store.load(order_id)
    rate = 0.2 if order.country == "GB" else 0.0
    if order.total > 1000:
        rate -= 0.05
    total = order.total * (1 + rate)
    store.save(replace(order, status="closed", total=total))
    return Receipt(order_id, total)

def price(order: Order) -> Decimal:
    rates = SqlRates(connect("rates.db"))
    return order.total * rates.for_country(order.country)

def main(argv: list[str]) -> int:
    store = FileStore(Path(argv[1]))
    for order in store.all():
        if order.due < date.today() and not order.paid:
            store.save(replace(order, status="late"))
    return 0

def close_order(order_id: str, *, store: OrderStore, clock: Clock) -> Receipt:
    order = store.load(order_id)
    closed = order.close(clock.now())
    store.save(closed)
    return receipt_for(closed)

def build(root: str) -> Container:
    store = FileStore(Path(root))
    return Container(store=store, clock=SystemClock())
